"""Editor HTML rendering."""
from .common import e, form, csrf

def editor(overlays, images, token, preview=''):
    thumbs = ''.join((f'''<div class="overlay-thumb" data-id="{o['id']}" title="{e(o['name'])}"><img src="/overlays/{e(o['path'])}" alt="{e(o['name'])}"></div>''' for o in overlays))
    photos = ''.join((f"""<div class="thumb-item"><img src="/uploads/{e(i['path'])}" alt="Your image">""" + form('delete-image', token, f'''<input type="hidden" name="image_id" value="{i['id']}">''', 'Delete').replace('class="btn btn-primary"', 'class="del-btn"') + '</div>' for i in images))
    return f'''<h1>📷 Studio</h1><div class="editor-wrap"><div class="editor-main"><div id="preview-wrap"><video id="webcam" autoplay playsinline muted style="display:none"></video><canvas id="canvas-preview" data-preview="{e('/uploads/' + preview if preview else '')}"></canvas></div><div style="display:flex;gap:.5rem;flex-wrap:wrap"><button class="btn btn-primary" id="btn-capture" disabled>📷 Capture</button><button class="btn btn-ghost" id="btn-retake" style="display:none">↩ Retake</button></div><form id="capture-form" method="post" action="/?page=capture" style="display:none">{csrf(token)}<input type="hidden" name="image_data" id="image_data"><input type="hidden" name="stickers" id="stickers_data"></form><details><summary>Or upload a photo instead</summary><input type="file" id="file-input" accept="image/png,image/jpeg,image/webp"></details><p>Select an overlay before capture. Drag to move, use corners to resize, double-click to remove.</p></div><aside class="editor-side"><div class="card"><h2>Cat overlays</h2><div class="overlay-list">{thumbs}</div></div><div class="card"><h2>Your photos</h2><div class="thumb-grid">{photos}</div></div></aside></div><script src="/js/editor.js"></script>'''
